const flags=new Map();if(mode!=='--worker')for(let n=3;n<process.argv.length;n+=2){const key=process.argv[n],value=process.argv[n+1];assert.ok(['--candidate','--archive-sha'].includes(key)&&value&&!flags.has(key));flags.set(key,value);}
