const forbidden = new Set([36994, 19387, 15832, 4180, 4280]);
const sha = bytes => createHash('sha256').update(bytes).digest('hex'), hash = path => sha(readFileSync(path));
const put = (name, value) => {const path = join(root, name); mkdirSync(dirname(path), {recursive: true}); writeFileSync(path, Buffer.isBuffer(value) || typeof value === 'string' ? value : JSON.stringify(value, null, 2) + '\n', {flag: 'wx', mode: 0o600}); return evidenceFile(path);};
