function inventory(base, current = base) {return readdirSync(current, {withFileTypes: true}).flatMap(entry => {if (excluded.has(entry.name)) return []; const path = join(current, entry.name); assert.equal(entry.isSymbolicLink(), false, path); return entry.isDirectory() ? inventory(base, path) : entry.isFile() ? [{path: relative(base, path).split(sep).join('/'), bytes: statSync(path).size, sha256: hash(path)}] : [];}).sort((a,b) => a.path.localeCompare(b.path));}
