const gone = pid => {try {process.kill(pid, 0); return false;} catch(error) {return error.code === 'ESRCH';}};
function local(value) {const url = new URL(value); assert.equal(url.hostname, '127.0.0.1'); assert.equal(url.protocol, 'http:'); assert.ok(!forbidden.has(Number(url.port))); return url;}
async function listen(server) {await new Promise((done, reject) => {server.once('error', reject); server.listen(0, '127.0.0.1', done);}); const url = 'http://127.0.0.1:' + server.address().port; local(url); return url;}
