  const input={sessionId:request.sessionId,params:{viewId:before.viewId,publicationId:before.publicationId,attemptId:before.attemptId,attemptEpoch:before.attemptEpoch,buildId:before.candidateBuildId,expectedViewRevision:before.expectedViewRevision}};
