  const recordName='manual-open/'+before.publicationId+'-'+randomUUID()+'.json',recordValue={scope:'FIXTURE',actualDesktopFrame:false,modelCapability:false,simulatedUiClick:true,automaticOpen:false,publicationBefore:before,fixedInput:input,opened,authorization:grant};
  const record=typeof put==='function'?put(recordName,recordValue):writeJson(join(root,recordName),recordValue);
