  const fourth=await click();await readAndReady(fourth.node,'fourth-document');state=await inspect();assert.equal(state.view.viewRevision,committedRevision);assert.equal(state.latestDisplay.generation,4);assert.equal(state.displays[0].state,'failed');assert.equal(state.displays[1].state,'failed');assert.equal(state.displays[2].state,'retired');assert.equal(state.displays[3].state,'ready');assert.equal(http.filter(row=>row.body?.operation==='openDisplay').length,4);assert.equal(http.filter(row=>row.body?.operation==='authorizeDisplayFrame').length,4);assert.equal(http.some(row=>['startMount','authorizeFrame','failMount'].includes(row.body?.operation)),false);assert.equal(nodes.length,4);
